import { unref } from 'vue'
import { session } from '../data/session'
import {
	readPortalState,
	removeLegacyStoragePrefix,
	removePortalState,
	writePortalState,
} from '../data/portalStorage'

function resolve(value) {
	return typeof value === 'function' ? value() : unref(value)
}

/** Penyimpanan state list per-user dan per-konteks route. */
export function useListPersistence(scope) {
	// Seluruh key filter lama bersifat global, jadi tidak aman dimigrasikan.
	removeLegacyStoragePrefix('dp-filter:', { kind: 'session' })
	const currentScope = () => String(resolve(scope) || 'unknown')
	const currentUser = () => session.user || 'anon'

	return {
		readSession(defaults = {}) {
			return readPortalState('session', currentUser(), currentScope(), defaults)
		},
		writeSession(data) {
			return writePortalState('session', currentUser(), currentScope(), data)
		},
		clearSession() {
			removePortalState('session', currentUser(), currentScope())
		},
		readPreferences(defaults = {}) {
			return readPortalState('pref', currentUser(), currentScope(), defaults)
		},
		writePreferences(data) {
			return writePortalState('pref', currentUser(), currentScope(), data)
		},
	}
}
